#include <cstddef>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <utility>
#include <vector>

struct Tick {
    int64_t ts_ns;          // nanoseconds since midnight
    double bid, ask;        // prices
    double bid_sz, ask_sz;  // sizes
};

struct Features {
    std::vector<Tick> ticks;
    std::vector<double> mids;
};

std::vector<Tick> load(int n) {
    std::vector<Tick> ticks;
    ticks.reserve(n);
    for (int i = 0; i < n; ++i) {
        double bid = 100.0 + (i % 7) * 0.25;
        ticks.push_back({34200000000000 + i * 1000000LL, bid, bid + 0.5, 300, 200});
    }
    return ticks;  // NRVO
}

Features build_features(std::vector<Tick> ticks) {
    Features f;
    f.mids.reserve(ticks.size());
    for (const Tick& t : ticks) {
        f.mids.push_back((t.bid + t.ask) / 2);
    }
    f.ticks = std::move(ticks);  // the buffer goes on, uncopied
    return f;  // NRVO
}

double simulate(const Features& f) {  // long 100 units: P&L from mid changes
    double pnl = 0.0;
    for (std::size_t i = 1; i < f.mids.size(); ++i) {
        pnl += 100 * (f.mids[i] - f.mids[i - 1]);
    }
    return pnl;
}

int main() {
    std::cout << std::boolalpha << std::fixed << std::setprecision(2);
    std::vector<Tick> raw = load(1000);
    const Tick* buffer = raw.data();
    std::cout << "loaded " << raw.size() << " ticks, " << raw.size() * sizeof(Tick) << " bytes\n";

    Features f = build_features(std::move(raw));
    std::cout << "moved: same buffer " << (f.ticks.data() == buffer) << ", raw has " << raw.size() << '\n';
    std::cout << "pnl " << simulate(f) << " over " << f.mids.size() << " mids\n";

    std::vector<Tick> again = load(1000);
    const Tick* second = again.data();
    Features g = build_features(again);  // no std::move: a full copy
    std::cout << "copied: same buffer " << (g.ticks.data() == second) << ", again has " << again.size() << '\n';
    return 0;
}

