#include <algorithm>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <utility>
#include <vector>

struct Tick {
    int64_t ts_ns;          // nanoseconds since midnight
    double bid, ask;        // prices
    double bid_sz, ask_sz;  // sizes
};

std::vector<Tick> load(int n) {
    std::vector<Tick> ticks;
    ticks.reserve(n);
    for (int i = 0; i < n; ++i) {
        double bid = 50.0 + (i % 5) * 0.5;
        double ask = (i % 4 == 3) ? bid - 0.25 : bid + 0.25 * (1 + i % 3);  // every 4th is crossed
        ticks.push_back({34200000000000 + i * 500000LL, bid, ask, 100, 100});
    }
    return ticks;
}

std::vector<Tick> clean(std::vector<Tick> ticks) {
    ticks.erase(std::remove_if(ticks.begin(), ticks.end(), [](const Tick& t) { return t.bid >= t.ask; }),
                ticks.end());
    return ticks;
}

double average_spread(const std::vector<Tick>& ticks) {
    if (ticks.empty()) {
        return 0.0;
    }
    double total = 0.0;
    for (const Tick& t : ticks) {
        total += t.ask - t.bid;
    }
    return total / ticks.size();
}

int main() {
    std::cout << std::boolalpha << std::fixed << std::setprecision(4);
    int n = 0;
    std::cin >> n;
    std::vector<Tick> raw = load(n);
    const Tick* buffer = raw.data();
    std::vector<Tick> good = clean(std::move(raw));
    std::cout << "same buffer " << (good.data() == buffer) << ", raw has " << raw.size() << '\n';
    std::cout << "kept " << good.size() << " of " << n << '\n';
    std::cout << "average spread " << average_spread(good) << '\n';
    return 0;
}

