void label(const char* line) {
    std::cout << "-- " << line << '\n';
}

struct Order {
    Order(int i, double p, int q) : id(i), price(p), qty(q) {}
    int id;
    double price;
    int qty;
    Tracker trace;  // counts this order's copies and moves
};

template <typename... Args>
Order& emplace_order(std::vector<Order>& orders, Args&&... args) {
    orders.emplace_back(std::forward<Args>(args)...);
    return orders.back();
}

int main() {
    std::vector<Order> orders;
    orders.reserve(8);  // no growth: only the calls count
    label("push_back(Order(1, 101.25, 300))");
    orders.push_back(Order(1, 101.25, 300));
    label("push_back({2, 101.5, 200})");
    orders.push_back({2, 101.5, 200});
    label("emplace_back(3, 101.75, 100)");
    orders.emplace_back(3, 101.75, 100);
    Order resting(4, 102.0, 500);
    label("push_back(resting)");
    orders.push_back(resting);
    label("emplace_back(resting)");
    orders.emplace_back(resting);
    label("emplace_back(std::move(resting))");
    orders.emplace_back(std::move(resting));
    label("emplace_order(orders, 5, 102.25, 50)");
    Order& last = emplace_order(orders, 5, 102.25, 50);
    std::cout << "last order " << last.id << ", " << orders.size() << " orders\n";
    std::cout << "copies " << Tracker::copies << ", moves " << Tracker::moves << '\n';
    return 0;
}

